from typing import Protocol, Mapping

class BoundedContext(Protocol):
    @property
    def name(self) -> str: ...
    @property
    def language(self) -> Mapping[str, str]: ...
    def owns(self, aggregate_type: type) -> bool: ...
    def translator_to(self, other: 'BoundedContext') -> object: ...

consumption_example:
def route(cmd, ctx: BoundedContext):
    if not ctx.owns(type(cmd.aggregate)):
        raise RuntimeError('wrong context')
    return ctx.handle(cmd)
